  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --bg-accent: #131b33;
        --panel: rgba(19, 27, 51, 0.88);
        --panel-border: rgba(148, 163, 184, 0.18);
        --text: #e5eefc;
        --muted: #a8b4cf;
        --accent: #8b9cff;
        --accent-strong: #b8c2ff;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(139, 156, 255, 0.16), transparent 34%),
          linear-gradient(180deg, #0a0f1f 0%, #060910 100%);
        color: var(--text);
      }

      .page-shell {
        width: min(920px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 4rem 0;
      }

      .hero {
        margin-bottom: 2rem;
        padding: 2rem;
        border: 1px solid rgba(139, 156, 255, 0.18);
        border-radius: 28px;
        background: linear-gradient(180deg, rgba(19, 27, 51, 0.92), rgba(11, 16, 32, 0.9));
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-strong);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.25rem, 5vw, 3.5rem);
        line-height: 1.05;
      }

      .hero p {
        max-width: 44rem;
        margin: 1rem 0 0;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq-list {
        display: grid;
        gap: 1rem;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        overflow: hidden;
        background: var(--panel);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
      }

      .question-button {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: 100%;
        padding: 1.2rem 1.35rem;
        border: 0;
        background: transparent;
        color: var(--text);
        text-align: left;
        font: inherit;
        font-size: 1.05rem;
        font-weight: 700;
        cursor: pointer;
      }

      .question-button:hover,
      .question-button:focus-visible {
        background: rgba(139, 156, 255, 0.08);
        outline: none;
      }

      .question-button:focus-visible {
        box-shadow: inset 0 0 0 2px rgba(184, 194, 255, 0.75);
      }

      .icon {
        flex: 0 0 auto;
        width: 2rem;
        height: 2rem;
        display: grid;
        place-items: center;
        border-radius: 999px;
        background: rgba(139, 156, 255, 0.14);
        color: var(--accent-strong);
        font-size: 1.15rem;
        transition: transform 180ms ease, background-color 180ms ease;
      }

      .question-button[aria-expanded="true"] .icon {
        transform: rotate(45deg);
        background: rgba(139, 156, 255, 0.24);
      }

      .details {
        padding: 0 1.35rem 1.35rem;
        color: var(--muted);
        line-height: 1.7;
      }

      .details[hidden] {
        display: none;
      }

      .details p {
        margin: 0;
      }

      @media (max-width: 640px) {
        .page-shell {
          width: min(100% - 1rem, 920px);
          padding: 1rem 0 2rem;
        }

        .hero,
        .question-button,
        .details {
          padding-left: 1rem;
          padding-right: 1rem;
        }
      }
    </style>
  </head>
  <body>
    <main id="app"></main>
    <script>
