        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed and content, but they may also purr to soothe themselves when stressed or recovering. The sound can serve as both a social signal and a calming mechanism."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day, with kittens and older cats often sleeping even more. Their bursts of play and alertness are balanced by lots of rest throughout the day."
        },
        {
          question: "Why do cats knead soft surfaces?",
          answer:
            "Kneading is a behavior that starts in kittenhood and often carries into adulthood. Cats may knead when they feel safe, comfortable, or are preparing a cozy resting spot."
        },
        {
          question: "What makes cats such effective hunters?",
          answer:
            "Cats combine excellent night vision, sharp hearing, quick reflexes, and precise movement. Even indoor cats keep these instincts, which is why toys that mimic prey can be especially engaging."
        }
      ];

      function h(tag, props = {}, ...children) {
        const element = document.createElement(tag);

        Object.entries(props).forEach(([key, value]) => {
          if (key === "className") {
            element.className = value;
          } else if (key.startsWith("on")) {
            element.addEventListener(key.slice(2).toLowerCase(), value);
          } else if (key === "text") {
            element.textContent = value;
          } else if (value !== undefined && value !== null) {
            element.setAttribute(key, value);
          }
        });

        children.flat().forEach((child) => {
          if (typeof child === "string") {
            element.appendChild(document.createTextNode(child));
          } else if (child) {
            element.appendChild(child);
          }
        });

        return element;
      }

      function FAQItem({ question, answer }, index) {
        const detailsId = `faq-details-${index}`;
        const details = h("div", {
          className: "details",
          id: detailsId,
          hidden: ""
        }, h("p", {}, answer));

        const button = h(
          "button",
          {
            className: "question-button",
            type: "button",
            "aria-expanded": "false",
            "aria-controls": detailsId,
            onClick: () => {
              const expanded = button.getAttribute("aria-expanded") === "true";
              button.setAttribute("aria-expanded", String(!expanded));

              if (expanded) {
                details.setAttribute("hidden", "");
              } else {
                details.removeAttribute("hidden");
              }
            }
          },
          h("span", {}, question),
          h("span", { className: "icon", "aria-hidden": "true" }, "+")
        );

        return h("div", { className: "example" }, button, details);
      }

      function FAQPage() {
        return h(
          "div",
          { className: "page-shell" },
          h(
            "section",
            { className: "hero" },
            h("p", { className: "eyebrow", text: "Cat knowledge base" }),
            h("h1", { text: "Frequently asked questions about cats" }),
            h(
              "p",
              {
                text:
                  "Explore quick answers about common feline habits, instincts, and behaviors. Each question starts collapsed, so the page stays clean until you want more detail."
              }
            )
          ),
          h(
            "section",
            { className: "faq-list", "aria-label": "Cat frequently asked questions" },
            faqs.map((item, index) => FAQItem(item, index))
          )
        );
      }

      document.getElementById("app").appendChild(FAQPage());
    </script>
  </body>
</html>
